"""[IMPORTANT] The following code is generated by AI and havn't been detailedly reviewed by human.[IMPORTANT]"""

"""Command-line builder for dense SDF assets used by numerical IK."""

import argparse
from pathlib import Path
import sys
from typing import Sequence

from .sdf_map import build_sdf_map


def _one_or_three(values: Sequence[float] | None, option: str):
    if values is None:
        return None
    if len(values) == 1:
        return float(values[0])
    if len(values) == 3:
        return tuple(float(value) for value in values)
    raise ValueError(f"{option} accepts either one value or three x/y/z values")


def create_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description=(
            "Bake a closed OBJ collision mesh into a dense, trilinear SDF NPZ "
            "for CasADi numerical IK. Distances are negative inside and positive outside."
        )
    )
    parser.add_argument("mesh", type=Path, help="watertight OBJ/mesh input")
    parser.add_argument("output", type=Path, help="output .npz path")
    parser.add_argument(
        "--voxel-size",
        type=float,
        required=True,
        help="cubic voxel edge length in the OBJ's units (normally meters)",
    )

    boundary = parser.add_mutually_exclusive_group()
    boundary.add_argument(
        "--padding",
        type=float,
        nargs="+",
        metavar="P",
        help=(
            "padding around mesh bounds: one value or three x/y/z values; "
            "default is 0.10"
        ),
    )
    boundary.add_argument(
        "--bounds",
        type=float,
        nargs=6,
        metavar=("XMIN", "YMIN", "ZMIN", "XMAX", "YMAX", "ZMAX"),
        help="explicit requested map bounds in mesh coordinates",
    )
    boundary.add_argument(
        "--map-size",
        type=float,
        nargs="+",
        metavar="SIZE",
        help="requested map side length: one value or three x/y/z values",
    )
    parser.add_argument(
        "--map-center",
        type=float,
        nargs=3,
        metavar=("X", "Y", "Z"),
        help="map center in mesh coordinates; valid only with --map-size",
    )
    parser.add_argument(
        "--batch-size",
        type=int,
        default=200_000,
        help="maximum points per Trimesh distance call (default: 200000)",
    )
    parser.add_argument(
        "--required-boundary-clearance",
        type=float,
        default=0.0,
        help=(
            "minimum conservative point-SDF value on every map face; normally "
            "max sphere radius + safety margin + cost activation distance"
        ),
    )
    parser.add_argument(
        "--slab-depth",
        type=int,
        default=4,
        help="number of z slices generated together (default: 4)",
    )
    parser.add_argument(
        "--max-voxels",
        type=int,
        default=100_000_000,
        help="refuse larger grids before allocating memory (default: 100000000)",
    )
    parser.add_argument(
        "--uncompressed",
        action="store_true",
        help="store an uncompressed NPZ for faster loading at a larger file size",
    )
    return parser


def main(argv: Sequence[str] | None = None) -> int:
    parser = create_parser()
    args = parser.parse_args(argv)
    try:
        padding = _one_or_three(args.padding, "--padding")
        map_size = _one_or_three(args.map_size, "--map-size")
        if args.map_center is not None and map_size is None:
            raise ValueError("--map-center requires --map-size")

        last_percent = -1

        def report_progress(done: int, total: int) -> None:
            nonlocal last_percent
            percent = int(100 * done / total)
            if percent != last_percent:
                print(f"\rBaking SDF: {percent:3d}%", end="", flush=True)
                last_percent = percent

        sdf_map = build_sdf_map(
            args.mesh,
            voxel_size=args.voxel_size,
            padding=padding,
            bounds=args.bounds,
            map_size=map_size,
            map_center=args.map_center,
            required_boundary_clearance=args.required_boundary_clearance,
            batch_size=args.batch_size,
            slab_depth=args.slab_depth,
            max_voxels=args.max_voxels,
            progress=report_progress,
        )
        print()
        output = sdf_map.save(args.output, compressed=not args.uncompressed)
    except (FileNotFoundError, ImportError, RuntimeError, ValueError) as error:
        print(f"error: {error}", file=sys.stderr)
        return 2

    dimensions = " x ".join(str(value) for value in sdf_map.values.shape)
    print(f"Saved: {output}")
    print(f"Grid: {dimensions} nodes, voxel={sdf_map.voxel_size:g}")
    print(
        "Bounds: "
        f"min={sdf_map.bounds_min.tolist()}, max={sdf_map.bounds_max.tolist()}"
    )
    print(
        "Sign: negative inside, positive outside; "
        f"conservative margin={sdf_map.interpolation_error_bound:.6g}"
    )
    print(
        "Minimum conservative boundary SDF: "
        f"{sdf_map.metadata['boundary_min_conservative_sdf']:.6g}"
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
